\label{main:spectrum}
Let $\mu\leqslant\nu<\kappa<\lambda$ be infinite cardinals. The following are equivalent:
\begin{enumerate}
\item $\kappa\leqslant2^\mu$;
\item there is a space $X$ such that every point admits a decreasing local $\pi$-base and
\begin{equation}\label{eq:target}
\pi\chi(X)=\mu,\qquad\pi\chi_l(X)=\nu,\qquad
\pi\chi_c(X)=\kappa,\qquad\pi\chi_d(X)=\lambda.
\end{equation}
\end{enumerate}
When these conditions hold, for each fixed integer $r\geqslant2$ there is a zero-dimensional Tychonoff witness of cardinality $\lambda$, with an $r$-linked local $\pi$-base of cardinality at most $\nu$ at every point, and
\[
\operatorname{ni}(X)=
\begin{cases}
1,&\lambda\text{ is regular},\\
\operatorname{cf}(\lambda),&\lambda\text{ is singular}.
\end{cases}
\]
These cardinalities are least possible among all spaces satisfying \eqref{eq:target}. The same four invariant values can also be realized by a crowded zero-dimensional Tychonoff space of cardinality $\lambda$.

\label{prop:extensions}
Let $\mathcal F$ be a free filter on $S$. Then
\begin{equation}\label{eq:extensions}
\pi\chi_c(p,X(\mathcal F))=
\min\{\chi(\mathcal G):\mathcal G\text{ is a proper filter on }S,\ \mathcal F\subseteq\mathcal G\}.
\end{equation}

\label{lem:finite}
Let $\mathcal F$ be a proper filter on $S$, let $\mathcal U$ be an ultrafilter on $T$, and let $f_i:S\to T$ for $i<r$, where $1\leqslant r<\omega$. Suppose
\begin{equation}\label{eq:finiteunion}
\bigcup_{i<r}f_i^{-1}(A)\in\mathcal F\qquad(A\in\mathcal U).
\end{equation}
Then there are an $\mathcal F$-positive set $a\subseteq S$ and an index $i<r$ such that
\[
(f_i)_*(\mathcal F_a)=\mathcal U.
\]
In particular, $\chi(\mathcal U)\leqslant\chi(\mathcal F)$.

\label{cor:ch}
Over ZFC, failure of the continuum hypothesis is equivalent to each of the following assertions:
\begin{enumerate}
\item there is a space with $\pi\chi=\pi\chi_l=\omega$, $\pi\chi_c=\omega_2$, and $\pi\chi_d=\omega_3$;
\item there is a space with $\pi\chi=\omega$, $\pi\chi_l=\omega_1$, $\pi\chi_c=\omega_2$, and $\pi\chi_d=\omega_3$.
\end{enumerate}
In either case the witness can be zero-dimensional and Tychonoff, of cardinality $\omega_3$, with exactly one non-isolated point, or instead crowded.
